#include <iostream>
#include <cstddef>

// Custom fixed-size buffer with nontype parameter N and default type int
template <typename T = int, std::size_t N = 5>
class StaticBuffer {
private:
    T data[N];
    std::size_t count{0};
public:
    bool push(const T& val) {
        if (count < N) {
            data[count++] = val;
            return true;
        }
        return false;
    }

    void print() const {
        for (std::size_t i = 0; i < count; ++i) {
            std::cout << data[i] << (i + 1 == count ? "" : " ");
        }
        std::cout << "\n";
    }

    std::size_t capacity() const { return N; }
};

int main() {
    // Uses both default type (int) and default size (5)
    StaticBuffer<> defaultBuf;
    defaultBuf.push(10);
    defaultBuf.push(20);
    defaultBuf.push(30);
    std::cout << "Default buffer (cap " << defaultBuf.capacity() << "): ";
    defaultBuf.print();

    // Overriding type to double, nontype size to 3
    StaticBuffer<double, 3> doubleBuf;
    doubleBuf.push(1.25);
    doubleBuf.push(3.75);
    std::cout << "Double buffer (cap " << doubleBuf.capacity() << "): ";
    doubleBuf.print();

    return 0;
}

#include <iostream>
#include <string>

// 1. Primary function template for two arguments of the same type
template <typename T>
void display(const T& a, const T& b) {
    std::cout << "Template (same type): " << a << ", " << b << "\n";
}

// 2. Overloaded function template with different parameter count
template <typename T>
void display(const T& a, const T& b, const T& c) {
    std::cout << "Template (three items): " << a << ", " << b << ", " << c << "\n";
}

// 3. Non-template function overload for const char*
void display(const char* a, const char* b) {
    std::cout << "Non-template overload: [" << a << ", " << b << "]\n";
}

int main() {
    // Calls Template 1 with T = int
    display(10, 20);

    // Calls Template 2 with T = double
    display(1.1, 2.2, 3.3);

    // Matches both Template 1 (T = const char*) and Non-template function.
    // Overload resolution chooses the non-template version!
    display("Apple", "Banana");

    return 0;
}
